'use strict';
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#main-nav');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('is-open',open)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('is-open')){nav.classList.remove('is-open');menu.setAttribute('aria-expanded','false');menu.focus()}});
const dialog=document.querySelector('#viewer'),content=document.querySelector('#dialog-content');
function show(node){content.replaceChildren(node);dialog.showModal();document.body.style.overflow='hidden'}
dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{document.body.style.overflow='';content.replaceChildren()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.querySelectorAll('[data-image]').forEach(b=>b.addEventListener('click',()=>{const box=document.createElement('div'),img=document.createElement('img'),cap=document.createElement('p');img.src=b.dataset.image;img.alt=b.dataset.caption;img.style.cssText='max-height:78dvh;object-fit:contain;width:100%;background:#092d57';cap.textContent=b.dataset.caption;cap.style.cssText='padding:14px 22px;margin:0;font-size:13px';box.append(img,cap);show(box)}));
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});document.querySelectorAll('[data-group]').forEach(x=>{x.hidden=b.dataset.filter!=='all'&&x.dataset.group!==b.dataset.filter})}));
document.querySelectorAll('[data-channel]').forEach(b=>b.addEventListener('click',()=>{const box=document.createElement('div');box.className='dialog-text';const title=document.createElement('h2'),p=document.createElement('p'),a=document.createElement('a');title.textContent=b.dataset.channel+' via Hydrocare';p.textContent='Dit contactkanaal wordt aangesloten zodra Daan het juiste '+(b.dataset.channel==='WhatsApp'?'WhatsApp-nummer':'Facebook-account')+' heeft bevestigd. In deze preview wordt geen bericht verstuurd.';a.className='button';a.href='/contact/#quote-form';a.textContent='Bekijk het demoformulier ↗';box.append(title,p,a);show(box)}));
const form=document.querySelector('#quote-form');if(form){const input=document.querySelector('#photos'),list=document.querySelector('#file-list'),error=document.querySelector('#file-error');let files=[];function render(){list.replaceChildren();files.forEach((f,i)=>{const row=document.createElement('div'),name=document.createElement('span'),remove=document.createElement('button');row.className='file-item';name.textContent=f.name+' · '+(f.size/1048576).toFixed(1)+' MB';remove.type='button';remove.textContent='Verwijderen';remove.setAttribute('aria-label',f.name+' verwijderen');remove.onclick=()=>{files.splice(i,1);render()};row.append(name,remove);list.append(row)})}input.addEventListener('change',()=>{error.textContent='';for(const f of input.files){if(files.length>=5){error.textContent='U kunt maximaal 5 foto’s toevoegen.';break}if(f.size>10*1048576){error.textContent='Een foto is groter dan 10 MB en werd niet toegevoegd.';continue}if(!/\.(jpe?g|png|webp|heic|heif)$/i.test(f.name)){error.textContent='Kies een JPG-, PNG-, WebP- of HEIC-foto.';continue}if(!files.some(x=>x.name===f.name&&x.size===f.size))files.push(f)}input.value='';render()});form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const box=document.createElement('div');box.className='dialog-text';const title=document.createElement('h2'),p=document.createElement('p'),dl=document.createElement('dl');title.textContent='Zo ziet uw demoaanvraag eruit.';p.textContent='Dit is een demonstratie. Uw aanvraag is niet verstuurd en wordt niet opgeslagen.';for(const [label,name] of [['Naam','naam'],['E-mailadres','email'],['Telefoonnummer','telefoon'],['Postcode en gemeente','gemeente'],['Onderwerp','dienst'],['Beschrijving','beschrijving']]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=form.elements[name].value||'Niet ingevuld';dl.append(dt,dd)}const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent='Foto’s';dd.textContent=files.length?files.map(f=>f.name).join(', '):'Geen foto’s geselecteerd';dl.append(dt,dd);box.append(title,p,dl);show(box)})}
